practice.solution:
def eliminate_rows(game):
    alive = list(range(len(game)))
    nc = len(game[0])
    changed = True
    while changed:
        changed = False
        for r in alive:
            for r2 in alive:
                if r2 == r:
                    continue
                dom = True
                for c in range(nc):
                    if not game[r2][c][0] > game[r][c][0]:
                        dom = False
                if dom:
                    alive.remove(r)
                    changed = True
                    break
            if changed:
                break
    return alive

