    for row in M:
        lo = min(row)
        if mm is None or lo > mm:
            mm = lo
    mx = None
    for c in range(len(M[0])):
        hi = M[0][c]
        for r in range(len(M)):
            if M[r][c] > hi:
                hi = M[r][c]
