def evolve(x0, A, dt, steps):
    x = float(x0)
    for i in range(steps):
        f1 = A[0][0] * x + A[0][1] * (1 - x)
        f2 = A[1][0] * x + A[1][1] * (1 - x)
        avg = x * f1 + (1 - x) * f2
        x = x + dt * x * (f1 - avg)
    return round(x, 2)

