practice.solution:
def shapley(v):
    orders = [[0, 1, 2], [0, 2, 1], [1, 0, 2], [1, 2, 0], [2, 0, 1], [2, 1, 0]]
    phi = [0.0, 0.0, 0.0]
    for o in orders:
        mask = 0
        for p in o:
            phi[p] = phi[p] + v[mask | (1 << p)] - v[mask]
            mask = mask | (1 << p)
    return [round(x / 6.0, 3) for x in phi]

