practice.solution:
def majority(ballots, a, b):
    na = 0
    nb = 0
    for r in ballots:
        if r.index(a) < r.index(b):
            na = na + 1
        else:
            nb = nb + 1
    if na > nb:
        return a
    if nb > na:
        return b
    return 'tie'
